import { useState } from 'react'

let next = 1000
export function TodoList({ initial }) {
  const [todos, setTodos] = useState(initial)
  return (
    <div>
      <button onClick={() => setTodos((t) => [{ id: next++, text: '' }, ...t])}>Add first</button>
      <ul>
        {todos.map((t) => (
          <li key={t.id}><input aria-label={'todo ' + t.id} defaultValue={t.text} /></li>
        ))}
      </ul>
    </div>
  )
}

