import { useState } from 'react'

export function PhoneInput({ onValid }) {
  const [v, setV] = useState('')
  return (
    <label>
      Phone
      <input
        value={v}
        onChange={(e) => {
          const next = e.target.value.replace(/\D/g, '').slice(0, 10)
          setV(next)
          if (next.length === 10) onValid?.(next)
        }}
      />
      {v.length === 10 && <span>✓ valid</span>}
    </label>
  )
}

