import { useState } from 'react'

export function validate({ email, password }) {
  const errors = {}
  if (!email.includes('@')) errors.email = 'Enter a valid email'
  if (password.length < 8) errors.password = 'At least 8 characters'
  return errors
}

export function SignupForm({ onSubmit }) {
  const [values, setValues] = useState({ email: '', password: '' })
  const [errors, setErrors] = useState({})
  const set = (k) => (e) => setValues((v) => ({ ...v, [k]: e.target.value }))
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault()
        const errs = validate(values)
        setErrors(errs)
        if (Object.keys(errs).length === 0) onSubmit(values)
      }}
    >
      <label>Email <input value={values.email} onChange={set('email')} aria-invalid={!!errors.email} /></label>
      {errors.email && <p role="alert">{errors.email}</p>}
      <label>Password <input type="password" value={values.password} onChange={set('password')} aria-invalid={!!errors.password} /></label>
      {errors.password && <p role="alert">{errors.password}</p>}
      <button>Sign up</button>
    </form>
  )
}

