export function matchPath(pattern, path) {
  const p = pattern.split('/').filter(Boolean)
  const s = path.split('/').filter(Boolean)
  const params = {}
  for (let i = 0; i < p.length; i++) {
    if (p[i] === '*') { params['*'] = s.slice(i).join('/'); return params }
    if (i >= s.length) return null
    if (p[i].startsWith(':')) params[p[i].slice(1)] = decodeURIComponent(s[i])
    else if (p[i] !== s[i]) return null
  }
  return p.length === s.length ? params : null
}

tests.code:
import { expect, test } from 'vitest'
import { matchPath } from './matchPath'

test('captures params', () => {
  expect(matchPath('/users/:id/posts/:postId', '/users/42/posts/7')).toEqual({ id: '42', postId: '7' })
  expect(matchPath('/a/:x', '/a/hello%20world')).toEqual({ x: 'hello world' })
})

test('rejects non-matching paths', () => {
  expect(matchPath('/users/:id', '/users')).toBeNull()
  expect(matchPath('/users/:id', '/users/1/extra')).toBeNull()
  expect(matchPath('/about', '/contact')).toBeNull()
})

test('splat and trailing slashes', () => {
  expect(matchPath('/files/*', '/files/a/b')).toEqual({ '*': 'a/b' })
  expect(matchPath('/about/', '/about')).toEqual({})
})

