import { renderHook } from '@testing-library/react'
import { StrictMode } from 'react'
import { expect, test } from 'vitest'
import { useConnection } from './useConnection'

function makeServer() {
  const s = { open: new Set(), calls: 0 }
  s.connect = (room) => { s.calls++; s.open.add(room); return () => s.open.delete(room) }
  return s
}

test('one open connection after a StrictMode mount', () => {
  const s = makeServer()
  renderHook(() => useConnection('a', s.connect), { wrapper: StrictMode })
  expect([...s.open]).toEqual(['a'])
  expect(s.calls).toBe(2)
})

test('switching rooms closes the old one', () => {
  const s = makeServer()
  const { rerender } = renderHook(({ r }) => useConnection(r, s.connect), { initialProps: { r: 'a' } })
  rerender({ r: 'b' })
  expect([...s.open]).toEqual(['b'])
})

test('unmount closes it', () => {
  const s = makeServer()
  const { unmount } = renderHook(() => useConnection('a', s.connect))
  expect(s.open.size).toBe(1)
  unmount()
  expect(s.open.size).toBe(0)
})

