import { useEffect, useState } from 'react'

export function Clock({ tick = 1000 }) {
  const [s, setS] = useState(0)
  useEffect(() => {
    const id = setInterval(() => setS((x) => x + 1), tick)
    return () => clearInterval(id)
  }, [tick])
  return <time>{s}</time>
}

